const OPERATIONAL_APPOINTMENT_STATUSES=new Set(['pending_confirmation','confirmed']);
function appointmentIsExpired(item,now=Date.now()){return item?.status==='pending_confirmation'&&(item.is_expired===true||new Date(item.starts_at).getTime()<now)}
function appointmentStateLabel(item){return appointmentIsExpired(item)?'Vencida':statusLabel(item?.status)}
function appointmentQueues(now=Date.now()){
  const appointments=(state.data?.appointments||[]).filter(item=>OPERATIONAL_APPOINTMENT_STATUSES.has(item.status));
  const future=appointments.filter(item=>new Date(item.starts_at).getTime()>=now&&!appointmentIsExpired(item,now)).sort((a,b)=>new Date(a.starts_at)-new Date(b.starts_at));
  const overdue=appointments.filter(item=>appointmentIsExpired(item,now)).sort((a,b)=>new Date(a.starts_at)-new Date(b.starts_at));
  return {future,overdue};
}
function localHandoffFallback(){return (state.inbox.conversations||[]).length?[]:(state.handoffs||[])}
function openHumanCases(){
  const conversations=activeConversations().filter(needsHuman).map(item=>({kind:'conversation',item}));
  const tickets=localHandoffFallback().filter(item=>item.status==='open').map(item=>({kind:'ticket',item}));
  return [...conversations,...tickets];
}
function terminology(){
  const configured=state.data?.config?.terminology||state.data?.terminology||{};
  return {
    singular:configured.customer_singular||configured.customer||'cliente',
    plural:configured.customer_plural||configured.customers||'clientes',
    record:configured.record_label||configured.customer_record||'Ficha de atención',
    intake:configured.intake_label||'Datos de admisión'
  };
}
function applyTerminology(){
  const terms=terminology(),pluralTitle=terms.plural.charAt(0).toUpperCase()+terms.plural.slice(1);
  const nav=$('[data-view="clientes"] b');if(nav)nav.textContent=pluralTitle;
  const copy=$('#customer-view-copy');if(copy)copy.textContent=`Contactos y ${terms.intake.toLowerCase()} reunidos desde la conversación y la agenda.`;
  const search=$('#customer-search');if(search)search.placeholder=`Buscar ${terms.singular} por nombre o teléfono`;
}
const confirmationMode=()=>state.data?.config?.confirmation_mode||'manual';
function confirmationCopy(status){return status==='confirmed'?'La reserva quedó confirmada.':status==='pending_confirmation'?'La solicitud quedó pendiente de confirmación.':'La solicitud fue creada.'}
let toastTimer;
function showToast(message){const toast=$('#operation-toast');if(!toast)return;clearTimeout(toastTimer);toast.textContent=message;toast.hidden=false;toast.classList.add('visible');toastTimer=setTimeout(()=>{toast.classList.remove('visible');toast.hidden=true},4200)}
function serviceIsBookable(service){return service?.active!==false&&service?.bookable!==false}
function resourceSupportsService(resource,serviceName){return !Array.isArray(resource?.services)||!resource.services.length||resource.services.some(name=>String(name).localeCompare(String(serviceName),undefined,{sensitivity:'base'})===0)}
function locationsForService(service,locations){
  const allowed=service?.locations||service?.location_names;
  if(!Array.isArray(allowed)||!allowed.length)return locations;
  return locations.filter(location=>allowed.some(value=>String(value?.name||value).localeCompare(String(location.name),undefined,{sensitivity:'base'})===0));
}
function refreshBookingOptions(){
  const catalog=state.data?.catalog||{},services=(catalog.services||[]).filter(serviceIsBookable),service=services.find(item=>item.name===$('#booking-service')?.value)||services[0];
  const resources=(catalog.resources||[]).filter(item=>resourceSupportsService(item,service?.name));
  const locations=locationsForService(service,catalog.locations||[]);
  if($('#booking-resource'))$('#booking-resource').innerHTML=optionList(resources);
  if($('#booking-location'))$('#booking-location').innerHTML=optionList(locations);
}

async function api(url,options={}){const key=sessionStorage.getItem('zeroagent-dashboard-key')||'';const headers={'content-type':'application/json','x-dashboard-key':key,...(options.headers||{})};const response=await fetch(url,{...options,headers});const data=await response.json().catch(()=>({}));if(response.status===401){location.reload();throw new Error('Sesión vencida, recargando…')}if(!response.ok)throw new Error(data.error||'No se pudo completar la acción.');return data}
async function previewApi(url,body){const key=sessionStorage.getItem('zeroagent-preview-key')||'';const response=await fetch(url,{method:'POST',headers:{'content-type':'application/json','x-preview-key':key},body:JSON.stringify(body)});const data=await response.json().catch(()=>({}));if(response.status===401){const entered=prompt('Ingresa la clave de preview:');if(entered){sessionStorage.setItem('zeroagent-preview-key',entered);return previewApi(url,body)}}if(!response.ok)throw new Error(data.error||'No se pudo probar el agente.');return data}

