function renderRuntimeFailure(error){console.error('La consola no pudo conectar con el runtime:',error);document.body.classList.add('runtime-failed');const workspace=document.querySelector('.workspace');if(workspace)workspace.innerHTML='<section class="runtime-error" role="alert"><span class="section-label">CONEXIÓN INTERRUMPIDA</span><h1>No pudimos cargar la operación real.</h1><p>No se muestran datos de demostración para evitar confusiones. Revisa la conexión del agente o vuelve a intentar.</p><button class="primary-button" type="button" onclick="location.reload()">Reintentar</button></section>'}
