let demoTourIndex=-1;
function tourNodes(){return {card:document.querySelector('.demo-tour-card'),spotlight:document.querySelector('.demo-tour-spotlight')}}
function ensureTourNodes(){let {card,spotlight}=tourNodes();if(!spotlight){spotlight=document.createElement('div');spotlight.className='demo-tour-spotlight';document.body.append(spotlight)}if(!card){card=document.createElement('aside');card.className='demo-tour-card';card.setAttribute('role','dialog');card.setAttribute('aria-live','polite');document.body.append(card)}return {card,spotlight}}
function positionTourSpotlight(){const step=demoTourSteps[demoTourIndex],spotlight=document.querySelector('.demo-tour-spotlight'),target=step&&document.querySelector(step.target);if(!spotlight||!target)return;const rect=target.getBoundingClientRect(),pad=8;spotlight.style.top=`${Math.max(8,rect.top-pad)}px`;spotlight.style.left=`${Math.max(8,rect.left-pad)}px`;spotlight.style.width=`${Math.min(innerWidth-16,rect.width+pad*2)}px`;spotlight.style.height=`${Math.min(innerHeight-16,rect.height+pad*2)}px`;spotlight.classList.add('visible')}
function showDemoTour(index){demoTourIndex=Math.max(0,Math.min(demoTourSteps.length-1,index));const step=demoTourSteps[demoTourIndex];document.body.classList.add('tour-running');if(step.view==='inbox'){state.activeConversationId='c-2';renderInbox()}if(step.view==='agenda'){state.agendaView='calendar';state.selectedResource='all';renderAgenda()}if(step.view==='quality'){state.qualityView='playground';renderQualityPane()}openView(step.view,false);const {card}=ensureTourNodes();card.innerHTML=`<header><span>${esc(step.label)}</span><button data-demo-tour-close aria-label="Cerrar recorrido">×</button></header><h2>${esc(step.title)}</h2><p>${esc(step.copy)}</p><div class="demo-tour-tip">${esc(step.tip)}</div><div class="demo-tour-progress"><i style="width:${((demoTourIndex+1)/demoTourSteps.length)*100}%"></i></div><div class="demo-tour-actions"><button data-demo-tour-prev ${demoTourIndex===0?'disabled':''}>← Anterior</button><button data-demo-tour-next>${demoTourIndex===demoTourSteps.length-1?'Terminar y explorar':'Siguiente →'}</button></div>`;requestAnimationFrame(()=>{const target=document.querySelector(step.target);target?.scrollIntoView({block:'center',behavior:'smooth'});setTimeout(positionTourSpotlight,260)})}
function closeDemoTour(){demoTourIndex=-1;document.body.classList.remove('tour-running');document.querySelector('.demo-tour-card')?.remove();document.querySelector('.demo-tour-spotlight')?.remove()}
function startDemoTour(){showDemoTour(0)}
addEventListener('resize',()=>{if(demoTourIndex>=0)positionTourSpotlight()});
