function renderHeader(){const active=activeConversations(),attention=active.filter(needsHuman).length,feedback=(state.data.feedback||[]).filter(item=>item.status!=='resolved').length,paused=state.control.mode==='paused';$('#business-name').textContent=state.data.business_name||'Mi negocio';$('.brand-mark').textContent=initials(state.data.business_name);$('#profile-avatar').textContent=initials(state.data.business_name);$('#nav-attention').textContent=attention||'';$('#nav-conversations').textContent=active.length||'';$('#nav-feedback').textContent=feedback||'';$('#sidebar-status').textContent=paused?'Agente pausado':'Agente activo';$('#agent-toggle').textContent=paused?'Reactivar agente':'Pausar agente';$('#agent-toggle').classList.toggle('is-paused',paused);$$('.live-dot').forEach(dot=>dot.style.background=paused?'#d06b64':'#6dd997');$$('.agenda-module').forEach(node=>node.hidden=!state.data.catalog?.services?.length)}

function filteredConversations(){const query=state.search.toLowerCase();return (state.inbox.conversations||[]).filter(item=>{if(state.inboxFilter==='attention'&&!needsHuman(item))return false;if(state.inboxFilter==='mine'&&!item.assigned_owner_id)return false;if(query&&!`${item.customer_name} ${item.customer_phone} ${lastMessage(item)}`.toLowerCase().includes(query))return false;return true})}
