function renderOverviewV2(){
  const cases=openHumanCases(),{future,overdue}=appointmentQueues(),feedback=(state.data.feedback||[]).filter(item=>item.status!=='resolved');
  const actionCount=cases.length+overdue.length;
  $('#metric-attention').textContent=cases.length;
  $('#metric-bookings').textContent=future.length;
  $('#metric-overdue').textContent=overdue.length;
  $('#metric-feedback').textContent=feedback.length;
  $('#today-title').textContent=actionCount?`${actionCount} pendiente${actionCount===1?'':'s'} para resolver.`:'Todo al día.';
  const detail=[];
  if(cases.length)detail.push(`${cases.length} derivación${cases.length===1?'':'es'} humana${cases.length===1?'':'s'}`);
  if(overdue.length)detail.push(`${overdue.length} solicitud${overdue.length===1?'':'es'} vencida${overdue.length===1?'':'s'}`);
  $('#today-copy').textContent=actionCount?`${detail.join(' y ')}. El contexto está listo para continuar.`:'No hay derivaciones abiertas ni solicitudes de reserva vencidas.';

  const strip=$('#attention-strip');
  strip.className=`attention-banner${actionCount?' visible':''}`;
  strip.innerHTML=actionCount?`<span><strong>${actionCount} acción${actionCount===1?'':'es'} pendiente${actionCount===1?'':'s'}</strong> · ${esc(detail.join(' · '))}</span><button class="text-button" data-go="${cases.length?'inbox':'agenda'}">Revisar ahora →</button>`:'';

  const caseRows=cases.map(entry=>{
    if(entry.kind==='conversation'){
      const item=entry.item;
      return `<article class="queue-row" data-open="${esc(item.id)}"><div><strong>${esc(item.customer_name||item.customer_phone||'Conversación')}</strong><small>${esc(item.handoff_reason||lastMessage(item)).slice(0,95)}</small></div><span class="status-pill handoff">Atención humana</span></article>`;
    }
    const item=entry.item;
    return `<article class="queue-row" data-open-local="${esc(item.id)}"><div><strong>${esc(item.customer_name||'Caso derivado')}</strong><small>${esc(item.reason||item.customer_message||'Necesita una persona').slice(0,95)}</small></div><span class="status-pill handoff">Sin resolver</span></article>`;
  });
  const overdueRows=overdue.map(item=>`<article class="queue-row overdue-row" data-appointment="${esc(item.id)}"><div><strong>${esc(item.customer_name)} · ${esc(item.service)}</strong><small>${formatDate(item.starts_at)} · sigue por confirmar</small></div><span class="status-pill overdue">Solicitud vencida</span></article>`);
  const priority=[...caseRows,...overdueRows].slice(0,6);
  $('#priority-queue').innerHTML=priority.join('')||'<div class="empty-state compact"><strong>Sin acciones urgentes</strong><p>Las derivaciones y solicitudes vencidas aparecerán aquí.</p></div>';

  $('#today-appointments').innerHTML=future.slice(0,4).map(item=>`<article class="compact-booking" data-appointment="${esc(item.id)}"><div><strong>${esc(item.customer_name)} · ${esc(item.service)}</strong><small>${formatDate(item.starts_at)} · ${esc(item.resource)}</small></div><span class="status-pill ${esc(item.status)}">${esc(statusLabel(item.status))}</span></article>`).join('')||'<div class="empty-state compact"><strong>Sin atenciones futuras</strong><p>Las nuevas reservas aparecerán aquí.</p></div>';

  const activities=[
    ...cases.slice(0,1).map(entry=>({title:'Intervención solicitada',copy:entry.kind==='conversation'?`${entry.item.customer_name||entry.item.customer_phone}: ${entry.item.handoff_reason||'requiere al equipo'}`:entry.item.reason||entry.item.customer_message,date:entry.item.updated_at||entry.item.created_at})),
    ...overdue.slice(0,1).map(item=>({title:'Solicitud vencida',copy:`${item.customer_name} · ${item.service}`,date:item.starts_at})),
    ...future.slice(0,1).map(item=>({title:'Próxima atención',copy:`${item.customer_name} · ${item.service}`,date:item.starts_at})),
    ...feedback.slice(0,1).map(item=>({title:'Corrección enviada',copy:item.correction_text,date:item.created_at}))
  ].slice(0,3);
  $('#owner-activity').innerHTML=activities.map(item=>`<article class="activity-event"><time>${formatDate(item.date)}</time><strong>${esc(item.title)}</strong><p>${esc(item.copy||'')}</p></article>`).join('')||'<article class="activity-event"><strong>Sin cambios pendientes</strong><p>La actividad relevante quedará registrada aquí.</p></article>';
}

function renderInboxFromLocalHandoffs(){
  const query=state.search.trim().toLowerCase();
  const tickets=(state.handoffs||[]).filter(ticket=>{
    if(state.inboxFilter==='attention'&&ticket.status!=='open')return false;
    if(state.inboxFilter==='mine')return false;
    return !query||`${ticket.customer_name||''} ${ticket.customer_message||''} ${ticket.reason||''}`.toLowerCase().includes(query);
  });
  if(!tickets.some(item=>item.id===state.selectedHandoffId))state.selectedHandoffId=tickets.find(item=>item.status==='open')?.id||tickets[0]?.id||null;
  $('#thread-total').textContent=`${tickets.length} caso${tickets.length===1?'':'s'} derivado${tickets.length===1?'':'s'}`;
  $('#thread-list').innerHTML=tickets.map(ticket=>`<button class="thread ${ticket.id===state.selectedHandoffId?'active':''}" data-handoff-ticket="${esc(ticket.id)}"><div class="thread-top"><strong>${esc(ticket.customer_name||'Caso derivado')}</strong><span class="status-pill ${ticket.status==='open'?'handoff':'confirmed'}">${ticket.status==='open'?'Sin resolver':'Resuelto'}</span></div><p>${esc(ticket.customer_message||ticket.reason||'Sin detalle')}</p><small>${formatDate(ticket.created_at)}</small></button>`).join('')||'<div class="empty-state"><strong>Sin casos para este filtro</strong><p>Las derivaciones abiertas aparecerán aquí.</p></div>';
  const ticket=tickets.find(item=>item.id===state.selectedHandoffId);
  $('#conversation-empty').hidden=Boolean(ticket);$('#conversation-content').hidden=!ticket;
  if(!ticket){$('#conversation-content').innerHTML='';return}
  $('#conversation-content').innerHTML=`<header class="conversation-head"><div><h2>${esc(ticket.customer_name||'Caso derivado')}</h2><p>${formatDate(ticket.created_at)} · derivación operativa</p></div><span class="status-pill ${ticket.status==='open'?'handoff':'confirmed'}">${ticket.status==='open'?'Sin resolver':'Resuelto'}</span></header><div class="contact-context"><span>${esc(ticket.reason||'Sin motivo informado')}</span></div><div class="message-stream"><article class="message inbound"><small>Escribió</small><div>${esc(ticket.customer_message||'Sin mensaje')}</div></article>${ticket.agent_reply?`<article class="message outbound"><small>Respondió el agente</small><div>${esc(ticket.agent_reply)}</div></article>`:''}</div>${ticket.status==='open'?`<div class="human-composer"><span>Revisa el contexto antes de continuar con esta persona.</span><button class="outline-button" data-resolve-handoff="${esc(ticket.id)}">Marcar resuelto</button></div>`:''}`;
}
function renderAgenda(){
  renderAgendaCore();
  const services=state.data.catalog.services||[],bookable=services.filter(serviceIsBookable),manual=confirmationMode()!=='automatic';
  const appointments=visibleAppointments();
  $('#appointment-list').innerHTML=appointments.map(item=>{const expired=appointmentIsExpired(item);return `<article class="appointment-row${expired?' overdue-row':''}" data-appointment="${esc(item.id)}"><div><strong>${esc(item.customer_name)} · ${esc(item.service)}</strong><small>${formatDate(item.starts_at)} · ${esc(item.resource)} · ${esc(item.reference)}</small></div><div class="right"><span class="status-pill ${expired?'overdue':esc(item.status)}">${esc(appointmentStateLabel(item))}</span>${item.status==='pending_confirmation'&&!expired?`<button class="small-button" data-booking-status="confirmed" data-booking="${esc(item.id)}">Confirmar</button>`:''}</div></article>`}).join('')||'<div class="empty-state"><strong>Sin reservas para este filtro</strong></div>';
  $('#service-list').innerHTML=services.map(item=>`<article class="catalog-row"><strong>${esc(item.name)}</strong><small>${esc(item.duration_minutes)} min · Capacidad ${esc(item.capacity||1)}${item.redirect_note?` · ${esc(item.redirect_note)}`:''}</small><span class="soft-pill ${item.bookable===false?'external':''}">${item.bookable===false?'Coordinación externa':money(item.price_clp??item.price)}</span></article>`).join('')||'<div class="empty-state compact"><strong>Sin servicios configurados</strong></div>';
  $('#booking-service').innerHTML=optionList(bookable);
  refreshBookingOptions();
  const openButton=$('#open-manual-booking');
  openButton.disabled=!bookable.length;openButton.textContent=manual?'＋ Nueva solicitud':'＋ Nueva reserva';openButton.title=bookable.length?'':'No hay servicios agendables en este canal.';
  $('#booking-dialog-title').textContent=manual?'Nueva solicitud':'Nueva reserva';
  $('#booking-mode-note').textContent=manual?'La hora quedará por confirmar hasta que el equipo la acepte.':'La hora quedará confirmada si sigue disponible al guardar.';
  $('#booking-submit').textContent=manual?'Crear solicitud':'Confirmar reserva';
}

