function openView(view,update=true){const terms=terminology(),pluralTitle=terms.plural.charAt(0).toUpperCase()+terms.plural.slice(1);state.currentView=view;$$('.view').forEach(node=>node.classList.toggle('active',node.id===`view-${view}`));$$('[data-view]').forEach(button=>button.classList.toggle('active',button.dataset.view===view));const titles={overview:['OPERACIÓN DE HOY','Buenos días','Aquí está lo que necesita atención.'],inbox:['ATENCIÓN EN VIVO','Conversaciones','Revisa, toma y resuelve sin salir de tu aplicación.'],agenda:['AGENDA COMPARTIDA','Tiempo y capacidad','Reservas, equipo y disponibilidad real.'],quality:['MEJORA CONTINUA','Calidad del agente','Prueba y corrige con trazabilidad.'],business:['CONFIGURACIÓN','Tu negocio','Información, equipo e integraciones.'],clientes:['CONTROL INTERNO',pluralTitle,`${terms.intake} y seguimiento operativo.`]};const value=titles[view];if(value){$('#page-kicker').textContent=value[0];$('#page-title').textContent=value[1];$('#page-subtitle').textContent=value[2]}if(update)window.scrollTo({top:0,behavior:'smooth'})}
