async function sendHuman(text){const thread=state.inbox.conversations.find(item=>item.id===state.activeConversationId),requestId=`human-${Date.now()}-${Math.random().toString(36).slice(2)}`;const optimistic={id:requestId,direction:'outbound',sender_type:'human',delivery_status:'sending',content:text,created_at:new Date().toISOString()};thread.messages.push(optimistic);renderInbox();if(isDemo()){setTimeout(()=>{optimistic.delivery_status='sent';thread.updated_at=new Date().toISOString();renderInbox()},350);return}try{await api(`/api/client/conversations/${thread.id}/messages`,{method:'POST',body:JSON.stringify({text,requestId,operatorName:ownerName(thread.assigned_owner_id)||'Equipo'})});await load()}catch(error){optimistic.delivery_status='failed';renderInbox();alert(error.message)}}
async function rateMessage(messageId,rating){const thread=state.inbox.conversations.find(item=>item.id===state.activeConversationId),index=thread.messages.findIndex(item=>item.id===messageId),reply=thread.messages[index]?.content||'',question=thread.messages.slice(0,index).reverse().find(item=>item.direction==='inbound')?.content||'';let expectedAnswer='';if(rating==='down'){expectedAnswer=prompt('¿Cómo debería haber respondido el agente?')||'';if(!expectedAnswer.trim())return}if(isDemo()){state.data.feedback.unshift({id:`fb-${Date.now()}`,rating,status:'new',question,reply,correction_text:expectedAnswer,created_at:new Date().toISOString()});render();return}await api('/api/client/feedback',{method:'POST',body:JSON.stringify({rating,expectedAnswer,conversationId:thread.id,messageId,question,reply,channel:thread.channel})});await load()}
