document.addEventListener('click',async event=>{const demoStep=event.target.closest('[data-demo-step]');if(demoStep){openView(demoStep.dataset.demoStep);$$('[data-demo-step]').forEach(button=>button.classList.toggle('active',button===demoStep));return}if(event.target.closest('[data-demo-reset]')){location.reload();return}const nav=event.target.closest('[data-view]');if(nav){openView(nav.dataset.view);return}const go=event.target.closest('[data-go]');if(go){openView(go.dataset.go);return}const queue=event.target.closest('[data-open]');if(queue){state.activeConversationId=queue.dataset.open;renderInbox();openView('inbox');return}const thread=event.target.closest('[data-thread]');if(thread){state.activeConversationId=thread.dataset.thread;renderInbox();return}const inboxFilter=event.target.closest('[data-inbox-filter]');if(inboxFilter){state.inboxFilter=inboxFilter.dataset.inboxFilter;$$('[data-inbox-filter]').forEach(button=>button.classList.toggle('active',button===inboxFilter));renderInbox();return}const agendaView=event.target.closest('[data-agenda-view]');if(agendaView){state.agendaView=agendaView.dataset.agendaView;renderAgendaPane();return}const qualityView=event.target.closest('[data-quality-view]');if(qualityView){state.qualityView=qualityView.dataset.qualityView;renderQualityPane();return}const businessView=event.target.closest('[data-business-view]');if(businessView){state.businessView=businessView.dataset.businessView;renderBusinessPane();return}const resource=event.target.closest('[data-resource-filter]');if(resource){state.selectedResource=resource.dataset.resourceFilter;renderAgenda();return}const appointment=event.target.closest('[data-appointment]');if(appointment&&!event.target.closest('[data-booking-status]')){openAppointment(appointment.dataset.appointment);return}const close=event.target.closest('[data-close-dialog]');if(close){$(`#${close.dataset.closeDialog}`).close();return}if(event.target.closest('#refresh-button')){await load();return}if(event.target.closest('#agent-toggle')||event.target.closest('#control-action')){await setControl(state.control.mode==='paused'?'active':'paused');return}if(event.target.closest('#open-manual-booking')){$('#booking-form').reset();$('#booking-dialog').showModal();return}if(event.target.closest('#open-hours')){$('#hours-form').reset();$('#hours-dialog').showModal();return}if(event.target.closest('#open-block')){$('#block-form').reset();$('#block-dialog').showModal();return}if(event.target.closest('#open-new-customer')){$('#new-customer-form').reset();$('#new-customer-error').textContent='';$('#new-customer-dialog').showModal();return}if(event.target.closest('#google-calendar-disconnect')){if(!confirm('¿Desconectar Google Calendar?'))return;try{await api('/api/client/google-calendar/disconnect',{method:'POST'});await loadGoogleCalendarStatus();showToast('Google Calendar desconectado.')}catch(error){alert(error.message)}return}const action=event.target.closest('[data-action]');if(action){await saveOperation(action.dataset.action==='take-conversation'?{status:'handoff',needs_human:true,handoff_reason:'Tomada desde la aplicación'}:{status:'active',needs_human:false,handoff_reason:''});return}const rate=event.target.closest('[data-rate]');if(rate){await rateMessage(rate.dataset.message,rate.dataset.rate);return}const pgMessage=event.target.closest('[data-playground-message]');if(pgMessage){state.selectedPlaygroundId=pgMessage.dataset.playgroundMessage;renderPlayground();return}const pgRate=event.target.closest('[data-playground-rate]');if(pgRate){if(pgRate.dataset.playgroundRate==='up')await submitPlaygroundFeedback('up');else{$('#playground-correction').hidden=false;$('#playground-send-correction').hidden=false;$('#playground-correction').focus()}return}if(event.target.closest('#playground-send-correction')){const expected=$('#playground-correction').value.trim();if(expected)await submitPlaygroundFeedback('down',expected);return}if(event.target.closest('#playground-reset')){state.playground=[];state.selectedPlaygroundId=null;renderPlayground();return}const status=event.target.closest('[data-booking-status]');if(status){if(isDemo()){state.data.appointments.find(item=>item.id===status.dataset.booking).status=status.dataset.bookingStatus;$('#appointment-detail-dialog').open&&$('#appointment-detail-dialog').close();render()}else{try{await api(`/api/agenda/appointments/${status.dataset.booking}`,{method:'PATCH',body:JSON.stringify({status:status.dataset.bookingStatus})});$('#appointment-detail-dialog').open&&$('#appointment-detail-dialog').close();await load()}catch(error){const errorEl=$('#appointment-detail-error');if(errorEl)errorEl.textContent=error.message;else alert(error.message)}}return}const remove=event.target.closest('[data-delete-rule]');if(remove){await api(`/api/agenda/availability-rules/${remove.dataset.deleteRule}`,{method:'DELETE'});await load();return}const removeBlock=event.target.closest('[data-delete-block]');if(removeBlock){if(isDemo()){state.data.blocks=(state.data.blocks||[]).filter(item=>item.id!==removeBlock.dataset.deleteBlock);render()}else{await api(`/api/agenda/availability-blocks/${removeBlock.dataset.deleteBlock}`,{method:'DELETE'});await load()}return}const shift=event.target.closest('[data-calendar-shift]');if(shift){state.calendarOffset+=Number(shift.dataset.calendarShift);renderAgenda();return}const segmentFilter=event.target.closest('[data-segment-filter]');if(segmentFilter){state.customerFilter=segmentFilter.dataset.segmentFilter;$$('[data-segment-filter]').forEach(button=>button.classList.toggle('active',button===segmentFilter));renderClientes();return}const customerRow=event.target.closest('[data-customer]');if(customerRow){openCustomerDetail(customerRow.dataset.customer);return}const segmentButton=event.target.closest('.segment-picker [data-segment]');if(segmentButton){const customerId=segmentButton.closest('.segment-picker').dataset.customerId;try{await api(`/api/client/customers/${encodeURIComponent(customerId)}`,{method:'PATCH',body:JSON.stringify({segment:segmentButton.dataset.segment})});$$('.segment-picker button').forEach(button=>button.classList.toggle('active',button===segmentButton));const customersRes=await api('/api/client/customers');state.customers=customersRes.customers||[];renderClientes()}catch(error){alert(error.message)}return}
  if(event.target.closest('#customer-bulk-clear')){state.customerSelected.clear();renderClientes();return}
  if(event.target.closest('#customer-bulk-mute')){const ids=[...state.customerSelected];if(!ids.length)return;try{await api('/api/client/customers',{method:'PATCH',body:JSON.stringify({ids,bot_muted:true})});state.customerSelected.clear();const customersRes=await api('/api/client/customers');state.customers=customersRes.customers||[];renderClientes()}catch(error){alert(error.message)}return}
  const muteButton=event.target.closest('[data-mute-customer]');if(muteButton){const customerId=muteButton.dataset.muteCustomer,nextMuted=muteButton.dataset.muted==='1';try{await api(`/api/client/customers/${encodeURIComponent(customerId)}`,{method:'PATCH',body:JSON.stringify({bot_muted:nextMuted})});const customersRes=await api('/api/client/customers');state.customers=customersRes.customers||[];renderClientes();openCustomerDetail(customerId)}catch(error){alert(error.message)}return}const saveNote=event.target.closest('[data-save-note]');if(saveNote){const textarea=saveNote.closest('.visit-card').querySelector('.visit-notes');try{await api(`/api/agenda/appointments/${saveNote.dataset.saveNote}`,{method:'PATCH',body:JSON.stringify({notes:textarea.value})});saveNote.textContent='Guardado ✓';setTimeout(()=>{saveNote.textContent='Guardar nota'},1500)}catch(error){alert(error.message)}return}const handoffTicket=event.target.closest('[data-handoff-ticket]');if(handoffTicket){state.selectedHandoffId=handoffTicket.dataset.handoffTicket;renderInbox();return}const resolveHandoff=event.target.closest('[data-resolve-handoff]');if(resolveHandoff){try{await api(`/api/client/handoffs/${resolveHandoff.dataset.resolveHandoff}`,{method:'PATCH',body:JSON.stringify({status:'resolved'})});const handoffsRes=await api('/api/client/handoffs');state.handoffs=handoffsRes.tickets||[];renderInbox()}catch(error){alert(error.message)}return}});
document.addEventListener('change',async event=>{if(event.target.matches('[data-operation="owner"]'))await saveOperation({assigned_owner_id:event.target.value});if(event.target.matches('[data-operation="priority"]'))await saveOperation({priority:event.target.value})});
$('#conversation-search').addEventListener('input',event=>{state.search=event.target.value;renderInbox()});
$('#customer-search').addEventListener('input',event=>{state.customerSearch=event.target.value;renderClientes()});
$('#knowledge-suggestion-form').addEventListener('submit',async event=>{event.preventDefault();try{await api('/api/client/knowledge/suggestions',{method:'POST',body:JSON.stringify({category:$('#knowledge-category').value,subject:$('#knowledge-subject').value,value:$('#knowledge-value').value})});event.target.reset();const knowledgeRes=await api('/api/client/knowledge');state.knowledge=knowledgeRes;renderKnowledge();$('#knowledge-suggestions-note').innerHTML=`Sugerencia enviada. Se revisará antes de activarse. <a href="${supportWaLink('Sugerencia de conocimiento enviada')}" target="_blank" rel="noopener">Avisar por WhatsApp →</a>`}catch(error){alert(error.message)}});
$('#new-customer-form')?.addEventListener('submit',async event=>{event.preventDefault();try{const {customer}=await api('/api/client/customers',{method:'POST',body:JSON.stringify({full_name:$('#new-customer-name').value,phone:$('#new-customer-phone').value})});$('#new-customer-dialog').close();const customersRes=await api('/api/client/customers');state.customers=customersRes.customers||[];renderClientes();openCustomerDetail(customer.id)}catch(error){$('#new-customer-error').textContent=error.message}});
$('#business-data-form')?.addEventListener('submit',async event=>{event.preventDefault();try{const item=(await api('/api/client/business-data',{method:'POST',body:JSON.stringify({label:$('#business-data-label').value,value:$('#business-data-value').value,category:$('#business-data-category').value})})).item;state.businessData=[item,...(state.businessData||[])];event.target.reset();renderKnowledge()}catch(error){alert(error.message)}});
$('#business-info-form')?.addEventListener('submit',async event=>{event.preventDefault();try{const item=(await api('/api/client/business-info',{method:'POST',body:JSON.stringify({text:$('#business-info-text').value})})).item;state.businessInfo=[item,...(state.businessInfo||[])];event.target.reset();renderKnowledge()}catch(error){alert(error.message)}});
$('#notification-settings-form')?.addEventListener('submit',async event=>{event.preventDefault();const errorEl=$('#notification-settings-error');if(errorEl)errorEl.textContent='';const payload={handoff_alert_enabled:$('#notif-handoff').checked,booking_alert_enabled:Boolean(state.notificationSettings?.booking_alert_enabled),failure_alert_enabled:Boolean(state.notificationSettings?.failure_alert_enabled),alert_phone:$('#notif-alert-phone').value};if(isDemo()){state.notificationSettings=payload;renderNotifications();showToast('Preferencias de atención guardadas.');return}try{const res=await api('/api/client/notification-settings',{method:'PATCH',body:JSON.stringify(payload)});state.notificationSettings=res.settings||payload;renderNotifications();showToast('Preferencias de atención guardadas.')}catch(error){if(errorEl)errorEl.textContent=error.message;else alert(error.message)}});
$('#ai-byok-provider')?.addEventListener('change',event=>{$('#ai-byok-base-row').hidden=event.target.value!=='compatible'});
$('#ai-byok-form')?.addEventListener('submit',async event=>{event.preventDefault();const button=event.target.querySelector('button[type="submit"]'),keyInput=$('#ai-byok-key'),payload={mode:'byok',provider:$('#ai-byok-provider').value,model:$('#ai-byok-model').value.trim(),baseUrl:$('#ai-byok-base').value.trim(),apiKey:keyInput.value};button.disabled=true;setAiAction('Validando y cifrando la clave en el servidor…');try{state.aiAccount=await api('/api/client/ai-account',{method:'PUT',body:JSON.stringify(payload)});renderAiPlan();setAiAction('Clave propia activada.');showToast('IA del negocio actualizada.')}catch(error){setAiAction(error.message,true)}finally{keyInput.value='';payload.apiKey='';button.disabled=false}});
document.addEventListener('submit',async event=>{if(event.target.id==='human-composer'){event.preventDefault();const input=$('#human-message'),text=input.value.trim();if(text){input.value='';await sendHuman(text)}}});
$('#playground-form').addEventListener('submit',async event=>{event.preventDefault();const input=$('#playground-input'),question=input.value.trim();if(question){input.value='';await sendPlayground(question)}});
$('#booking-form').addEventListener('submit',async event=>{event.preventDefault();const submit=$('#booking-submit'),manual=confirmationMode()!=='automatic',item={id:`apt-${Date.now()}`,reference:'RSV-DEMO',customer_name:$('#booking-name').value,customer_phone:$('#booking-phone').value,customer_email:$('#booking-email').value,service:$('#booking-service').value,resource:$('#booking-resource').value,location:$('#booking-location').value,starts_at:$('#booking-starts').value,status:manual?'pending_confirmation':'confirmed',source:'client_console',notes:$('#booking-notes').value};$('#booking-error').textContent='';submit.disabled=true;try{let created;if(isDemo()){state.data.appointments.unshift(item);created=item;render()}else{const response=await api('/api/agenda/appointments',{method:'POST',body:JSON.stringify(item)});created=response.appointment;await load()}$('#booking-dialog').close();showToast(confirmationCopy(created?.status))}catch(error){$('#booking-error').textContent=error.message}finally{submit.disabled=false}});
$('#hours-form').addEventListener('submit',async event=>{event.preventDefault();const item={id:`rule-${Date.now()}`,resource:$('#hours-resource').value,day_of_week:Number($('#hours-day').value),starts_at:$('#hours-start').value,ends_at:$('#hours-end').value};try{if(isDemo())state.data.availabilityRules.push(item);else await api('/api/agenda/availability-rules',{method:'POST',body:JSON.stringify(item)});$('#hours-dialog').close();isDemo()?render():await load()}catch(error){$('#hours-error').textContent=error.message}});
$('#block-form').addEventListener('submit',async event=>{event.preventDefault();const item={id:`block-${Date.now()}`,resource:$('#block-resource').value,reason:$('#block-reason').value,starts_at:$('#block-starts').value,ends_at:$('#block-ends').value};try{if(isDemo())state.data.blocks=[...(state.data.blocks||[]),item];else await api('/api/agenda/availability-blocks',{method:'POST',body:JSON.stringify(item)});$('#block-dialog').close();isDemo()?render():await load()}catch(error){$('#block-error').textContent=error.message}});
document.addEventListener('click',event=>{const mode=event.target.closest('[data-calendar-mode]');if(!mode)return;state.calendarMode=mode.dataset.calendarMode;state.calendarOffset=0;renderAgenda()});
document.addEventListener('click',event=>{if(event.target.closest('[data-demo-tour-start]')){event.stopImmediatePropagation();startDemoTour();return}if(event.target.closest('[data-demo-tour-close]')){event.stopImmediatePropagation();closeDemoTour();return}if(event.target.closest('[data-demo-tour-prev]')){event.stopImmediatePropagation();showDemoTour(demoTourIndex-1);return}if(event.target.closest('[data-demo-tour-next]')){event.stopImmediatePropagation();demoTourIndex===demoTourSteps.length-1?closeDemoTour():showDemoTour(demoTourIndex+1)}},true);
installCommercialDemo();
function startLoad(){load().then(()=>{if(!commercialDemo){loadAiAccount().catch(()=>{});loadGoogleCalendarStatus().catch(()=>{});handleGoogleCalendarRedirectParams()}if(commercialDemo&&!embeddedDemo&&new URLSearchParams(location.search).get('tour')==='1')startDemoTour()}).catch(error=>console.error(error))}
// El demo comercial no necesita sesión real. Fuera de eso, hay que esperar a que auth-gate.js
// confirme que hay una sesión de operador antes de pedir datos — si no, esta llamada corre en
// paralelo a la pantalla de PIN, recibe 401 y termina compitiendo por la pantalla con ella.
if(commercialDemo||window.zaAuthenticated)startLoad();else document.addEventListener('za-authenticated',startLoad,{once:true});
